@Test(dependsOnMethods = { "testLoadJobConfigsWithDoneFile", "testLoadJobConfigsForCommonPropsFile", "testLoadJobConfig" })
public void testFileAlterationObserver() throws Exception {
    FileAlterationMonitor monitor = new FileAlterationMonitor(3000);
    final Set<File> fileAltered = Sets.newHashSet();
    final Semaphore semaphore = new Semaphore(0);
    FileAlterationListener listener = new FileAlterationListenerAdaptor() {

        @Override
        public void onFileCreate(File file) {
            fileAltered.add(file);
            semaphore.release();
        }

        @Override
        public void onFileChange(File file) {
            fileAltered.add(file);
            semaphore.release();
        }
    };
    SchedulerUtils.addFileAlterationObserver(monitor, listener, JOB_CONF_ROOT_DIR);
    try {
        monitor.start();
        // Give the monitor some time to start
        Thread.sleep(1000);
        File jobConfigFile = new File(SUB_DIR11, "test111.pull");
        Files.touch(jobConfigFile);
        File commonPropsFile = new File(SUB_DIR1, "test.properties");
        Files.touch(commonPropsFile);
        File newJobConfigFile = new File(SUB_DIR11, "test112.pull");
        Files.append("k1=v1", newJobConfigFile, ConfigurationKeys.DEFAULT_CHARSET_ENCODING);
        semaphore.acquire(3);
        Assert.assertEquals(fileAltered.size(), 3);
        Assert.assertTrue(fileAltered.contains(jobConfigFile));
        Assert.assertTrue(fileAltered.contains(commonPropsFile));
        Assert.assertTrue(fileAltered.contains(newJobConfigFile));
    } finally {
        monitor.stop();
    }
}

@Test
public void testTimeRangeChecker() {
    // January 1st, 2015 (a Thursday)
    DateTime dateTime = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeZone.forID("America/Los_Angeles"));
    // Positive Tests
    // Base hour
    Assert.assertTrue(TimeRangeChecker.isTimeInRange(Lists.newArrayList("THURSDAY"), "00-00", "06-00", dateTime));
    // Valid minute
    Assert.assertTrue(TimeRangeChecker.isTimeInRange(Lists.newArrayList("THURSDAY"), "00-00", "00-01", dateTime));
    // Multiple days
    Assert.assertTrue(TimeRangeChecker.isTimeInRange(Lists.newArrayList("MONDAY", "THURSDAY"), "00-00", "06-00", dateTime));
    // Negative Tests
    // Invalid day
    Assert.assertFalse(TimeRangeChecker.isTimeInRange(Lists.newArrayList("MONDAY"), "00-00", "06-00", dateTime));
    // Invalid minute
    Assert.assertFalse(TimeRangeChecker.isTimeInRange(Lists.newArrayList("THURSDAY"), "00-01", "06-00", dateTime));
    // Invalid hour
    Assert.assertFalse(TimeRangeChecker.isTimeInRange(Lists.newArrayList("THURSDAY"), "01-00", "06-00", dateTime));
}

